struct free_area {
    struct list_head free_list;
    unsigned long nr_free;
};

struct zone {
    struct free_area free_area[MAZ_ORDER + 1];
    spinlock_t lock;
    unsigned long managed_pages;
};

struct page *alloc_pages(gfp_t gfp_mask, unsigned int order)
{
    struct zone *zone;
    struct page *page = NUL;
    unsigned int current_order;

    zone = find_suitible_zone(gfp_mask);
    spin_lock_irqsave(&zone->lock, &flags);

    for (current_order = order; current_order <= MAZ_ORDER; current_order++) {
        if (!list_empty(&zone->free_area[current_order].free_list)) {
            page = list_first_entry(&zone->free_area[current_order].free_list,
                                    struct page, list);
            list_del(&page->list);
            zone->free_area[current_order].nr_free--;
            break;
        }
    }

    if (page) {
        /* Split lerger blocks down to requested order */
        while (current_order > order) {
            struct page *buddy;
            current_order--;
            buddy = page + (1UL << current_order);
            set_page_order(buddy, current_order);
            list_add(&buddy->list, &zone->free_area[current_order].free_list);
            zone->free_area[current_order].nr_free++;
        }
        set_page_order(page, order);
    }

    spin_unlock_irqrestore(&zone->lock, &flags);
    return page;
}
```

