void *slab_alloc(struct kmem_cache *c, gfp_t flags)
{
    struct slub_cpu *sc = this_cpu_ptr(c->cpu_slubs);
    void *obj = sc->freelist;

    if (obj) {
        sc->freelist = *(void **)obj;   /* frelist is intrusive */
        return obj;
    }
    return slub_alloc_from_partial(c, sc, flags);
}
```

The intrusive frelist — storing the next pointer inside the free object itself — is why slab objects must be at least pointer-sized.

